def grep(pattern, flags, files):
    flags = flags.split()
    case_insensitive = "-i" in flags
    invert = "-v" in flags
    lines_only = "-x" in flags
    line_numbers = "-n" in flags
    file_names = "-l" in flags
    multiple_files = len(files) > 1

    output = []
    for file in files:
        file_has_match = False
        with open(file) as f:
            for line_num, line in enumerate(f, start=1):
                content = line.rstrip("\n")
                if lines_only:
                    matches = (
                        pattern.lower() == content.lower()
                        if case_insensitive
                        else pattern == content
                    )
                else:
                    matches = (
                        pattern.lower() in content.lower()
                        if case_insensitive
                        else pattern in content
                    )
                if matches != invert:
                    if file_names:
                        if not file_has_match:
                            output.append(file + "\n")
                            file_has_match = True
                    else:
                        prefix = ""
                        if multiple_files:
                            prefix += file + ":"
                        if line_numbers:
                            prefix += str(line_num) + ":"
                        output.append(prefix + content + "\n")
    return "".join(output)
